LPCTSTR GetPegasoString(EPegasoString id)
{
	if (id < 0 || id >= PS_COUNT)
		return _T("");
	const WORD wPrimary = PRIMARYLANGID(thePrefs.GetLanguageID());
	for (int i = 1; i < LANG_COUNT; ++i)
		if (s_awPrimary[i] == wPrimary)
			return s_apszText[id][i];
	return s_apszText[id][0];
}
